package com.bites.dto.response;

import java.math.BigDecimal;
import java.util.List;

// This is the full cart, sent to the frontend as one object.
public record CartResponse(

        // Database id of the cart row.
        Long id,

        // The guest's session id (generated by the frontend and stored in the
        // browser). This is how a guest's cart is found again on their next visit.
        String sessionId,

        // All the items currently in this cart.
        List<CartItemResponse> items,

        // Sum of every item's subtotal — the total price before delivery
        // charge is added (delivery charge only applies at checkout).
        BigDecimal subtotal
) {
}
